package fr.mavoixecrite;
import android.app.*;import android.content.Context;import android.view.*;import android.widget.*;import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,35})
public class SwipeTest {
 Context context;float density;long time;
 @Before public void reset(){context=RuntimeEnvironment.getApplication();density=context.getResources().getDisplayMetrics().density;for(String n:new String[]{DataFile.NAME,DataFile.NAME+".new","phrases-v2.json"})new File(context.getFilesDir(),n).delete();for(String n:new String[]{"options","draft","MainActivity","conversation","voice"})context.getSharedPreferences(n,0).edit().clear().commit();time=android.os.SystemClock.uptimeMillis();}
 void event(View view,int action,float x,float y,boolean dispatch){MotionEvent e=MotionEvent.obtain(time,time+=20,action,x*density,y*density,0);if(dispatch)view.dispatchTouchEvent(e);else view.onTouchEvent(e);e.recycle();if(action==MotionEvent.ACTION_UP)Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 FamilyScrollView surface(Activity a,int[] changed,int[] clicked){FamilyScrollView scroll=new FamilyScrollView(a,n->changed[0]+=n);LinearLayout content=new LinearLayout(a);content.setOrientation(LinearLayout.VERTICAL);Button card=new Button(a);card.setText("Parler");card.setOnClickListener(v->clicked[0]++);content.addView(card,new LinearLayout.LayoutParams(-1,(int)(300*density)));content.addView(new View(a),new LinearLayout.LayoutParams(-1,(int)(1000*density)));scroll.addView(content);a.setContentView(scroll);int size=(int)(400*density);scroll.measure(View.MeasureSpec.makeMeasureSpec(size,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(size,View.MeasureSpec.EXACTLY));scroll.layout(0,0,size,size);return scroll;}
 @Test public void swipeOverCardNavigatesWithoutSpeaking(){try(ActivityController<Activity> ctl=Robolectric.buildActivity(Activity.class).setup()){int[] changed={0},clicked={0};FamilyScrollView scroll=surface(ctl.get(),changed,clicked);event(scroll,0,300,100,true);event(scroll,2,160,105,true);event(scroll,1,80,105,true);assertEquals(1,changed[0]);assertEquals(0,clicked[0]);}}
 @Test public void tapStillSpeaks(){try(ActivityController<Activity> ctl=Robolectric.buildActivity(Activity.class).setup()){int[] changed={0},clicked={0};FamilyScrollView scroll=surface(ctl.get(),changed,clicked);event(scroll,0,200,100,true);event(scroll,1,200,100,true);assertEquals(0,changed[0]);assertEquals(1,clicked[0]);}}
 @Test public void verticalScrollDoesNotChangeFamilyOrSpeak(){try(ActivityController<Activity> ctl=Robolectric.buildActivity(Activity.class).setup()){int[] changed={0},clicked={0};FamilyScrollView scroll=surface(ctl.get(),changed,clicked);event(scroll,0,200,250,true);event(scroll,2,205,120,true);event(scroll,1,210,40,true);assertEquals(0,changed[0]);assertEquals(0,clicked[0]);}}
 @Test public void shortDiagonalDoesNotNavigate(){try(ActivityController<Activity> ctl=Robolectric.buildActivity(Activity.class).setup()){int[] changed={0},clicked={0};FamilyScrollView scroll=surface(ctl.get(),changed,clicked);event(scroll,0,200,200,true);event(scroll,2,165,170,true);event(scroll,1,160,160,true);assertEquals(0,changed[0]);}}
 @Test public void mainSwipeKeepsDraftAndStopsAtEnds(){try(ActivityController<MainActivity> ctl=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=ctl.get();EditText draft=a.findViewById(R.id.message_input);draft.setText("Mon message à conserver");View scroll=a.findViewById(R.id.family_scroll);for(int i=0;i<3;i++){event(scroll,0,300,100,false);event(scroll,2,160,105,false);event(scroll,1,80,105,false);}assertEquals("Discussion",context.getSharedPreferences("options",0).getString("category",""));assertNotNull(AppTest.find(a.getWindow().getDecorView(),"Je vous écoute"));assertEquals("Mon message à conserver",draft.getText().toString());event(scroll,0,80,100,false);event(scroll,2,220,105,false);event(scroll,1,300,105,false);assertEquals("Besoins",context.getSharedPreferences("options",0).getString("category",""));}}
}
